        heading: "What is an anal fissure?",
        blocks: [
          { kind: "text", text: "An anal fissure is a small tear in the lining of the anal canal. It commonly develops when hard stools, constipation or other factors cause excessive stretching or injury to the anal lining." },
          { kind: "text", text: "Fissures can be acute or chronic. Acute anal fissures are relatively recent tears that often improve with appropriate bowel management and medical treatment. Chronic anal fissures persist for a longer period and may be associated with muscle spasm, a visible skin tag or other characteristic changes." },
          { kind: "text", text: "Not every fissure requires surgery." },
        ],
