              "Avoid repeated self-medication for unexplained pain.",
              "Seek medical advice for recurrent symptoms.",
              "Obtain urgent assessment if warning signs develop.",
              "Do not eat or drink while awaiting emergency surgical assessment if a clinician has instructed you to remain fasting.",
