        heading: "Final answer",
        blocks: [
          { kind: "text", text: "Most abdominal pain is not an emergency and does not require surgery, but certain warning signs — sudden severe pain, a rigid abdomen, persistent vomiting, fever with pain, or significant bleeding — should never be waited out. Pain location and character are useful clues, not a diagnosis; the right next step is a clinical assessment that can tell the difference between something that will settle on its own and something that needs urgent care." },
        ],
